    font-size: 0.9rem;
}

.sessions-table th,
.sessions-table td {
    padding: 0.75rem;
    text-align: left;
    border-bottom: 1px solid #e0e0e0;
}

.sessions-table th {
    background: #f8f9fa;
    font-weight: 600;
    color: #444;
}

.sessions-table tr:hover {
    background: #f9f9f9;
}

.current-session-badge {
    font-size: 0.8rem;
    background: #e8f0fe;
    color: #1a73e8;
    padding: 0.2rem 0.5rem;
    border-radius: 4px;
