.modal-dialog h3 {
    margin-top: 0;
}

/* Radio group */
.radio-group {
    display: flex;
    gap: 1.5rem;
    margin-top: 0.25rem;
}

.radio-label {
    display: flex;
    align-items: center;
    gap: 0.4rem;
    cursor: pointer;
    font-size: 0.9rem;
}

.radio-label input[type="radio"] {
    accent-color: #1a73e8;
}

/* Live preview */
.live-preview {
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    overflow: hidden;
    margin-top: 0.75rem;
    display: grid;
    grid-template-columns: 100px 1fr;
    grid-template-rows: auto 1fr;
    min-height: 150px;
}

.preview-header {
    grid-column: 1 / -1;
    padding: 0.75rem 1rem;
    font-weight: 600;
    border-bottom: 1px solid #e0e0e0;
}

.preview-sidebar {
    padding: 0.75rem;
    border-right: 1px solid #e0e0e0;
    font-size: 0.85rem;
}

.preview-body {
    padding: 0.75rem 1rem;
}

.preview-body p {
    margin: 0.25rem 0;
}

/* Preview theme variants */
.preview-theme-light {
    background: #ffffff;
    color: #333;
}

.preview-theme-light .preview-header {
    background: #f0f0f0;
}

.preview-theme-light .preview-sidebar {
    background: #f8f8f8;
}

.preview-theme-dark {
    background: #1e1e1e;
    color: #e0e0e0;
}

.preview-theme-dark .preview-header {
    background: #2d2d2d;
    border-color: #444;
}

.preview-theme-dark .preview-sidebar {
    background: #252525;
    border-color: #444;
}

.preview-theme-system {
    background: #f5f5f5;
    color: #333;
}

.preview-theme-system .preview-header {
    background: #e8e8e8;
}

.preview-theme-system .preview-sidebar {
    background: #efefef;
}

/* Preview font sizes */
.preview-font-small {
    font-size: 0.8rem;
}

.preview-font-medium {
    font-size: 0.95rem;
}

.preview-font-large {
    font-size: 1.15rem;
}

/* Preview compact mode */
.preview-compact .preview-header,
.preview-compact .preview-sidebar,
.preview-compact .preview-body {
    padding: 0.35rem 0.5rem;
}

.preview-compact {
    min-height: 100px;
}

/* Toast */
.toast {
    position: fixed;
    bottom: 2rem;
    right: 2rem;
    padding: 0.75rem 1.25rem;
    border-radius: 8px;
    font-size: 0.9rem;
    display: flex;
    align-items: center;
    gap: 0.75rem;
    box-shadow: 0 4px 16px rgba(0, 0, 0, 0.15);
    z-index: 2000;
    animation: slideIn 0.3s ease;
}

.toast.success {
    background: #d4edda;
    color: #155724;
    border: 1px solid #c3e6cb;
}

.toast.error {
    background: #f8d7da;
    color: #721c24;
    border: 1px solid #f5c6cb;
}

.toast.info {
    background: #d1ecf1;
    color: #0c5460;
    border: 1px solid #bee5eb;
}

.toast-close {
    background: none;
    border: none;
    cursor: pointer;
    font-size: 1rem;
    opacity: 0.6;
}

.toast-close:hover {
    opacity: 1;
}

@keyframes slideIn {
    from {
        transform: translateY(1rem);
        opacity: 0;
    }
    to {
        transform: translateY(0);
        opacity: 1;
    }
}

/* Loading */
.loading-spinner {
    padding: 3rem;
    text-align: center;
    color: #888;
    font-size: 1.1rem;
}

.info-text {
    font-size: 0.85rem;
    color: #666;
    margin-top: 0.5rem;
}
"}

